using System;using System.IO;using System.Linq;using System.Collections.Generic;
namespace Musikbox {
 public sealed class TagDefinition{public readonly string Name,Format,Key,Column;public readonly bool Writable;public bool DefaultVisible{get{return Key!="_bitrate"&&Key!="_length"&&Key!="_tag"&&Key!="acoustid_id";}}public TagDefinition(string name,string key,string column,bool writable){Name=name;Key=key;Column=column;Writable=writable;Format="%"+key+"%";}}
 public static class TagSchema {
  public static readonly TagDefinition[] Fields={new TagDefinition("Interpret","artist","Interpret",true),new TagDefinition("Titel","title","Titel",true),new TagDefinition("Ordner","_directory","Ordner",false),new TagDefinition("Track","track","Tracknummer",true),new TagDefinition("Genre","genre","Genre",true),new TagDefinition("Jahr","year","Jahr",true),new TagDefinition("Album","album","Album",true),new TagDefinition("Dateiname","_filename_ext","Quelle",false),new TagDefinition("Pfad","_path","Dateipfad",false),new TagDefinition("Bitrate","_bitrate","Bitrate",false),new TagDefinition("Länge","_length","Dauer",false),new TagDefinition("Tag","_tag","Tag",false),new TagDefinition("AcoustID","acoustid_id","AcoustidId",true)};
  public static string Length(double seconds){int total=Math.Max(0,(int)seconds);return total>=3600?(total/3600)+":"+((total/60)%60).ToString("D2")+":"+(total%60).ToString("D2"):(total/60).ToString("D2")+":"+(total%60).ToString("D2");}
  public static string Value(Song song,string key){switch(key){case "acoustid_id":return song.AcoustidId??"";case "ordner":return song.FolderName??"";case "artist":return song.Artist??"";case "title":return song.Title??"";case "track":return song.Track??"";case "genre":return song.Genre??"";case "year":return song.Year??"";case "album":return song.Album??"";case "_directory":return Path.GetFileName(Path.GetDirectoryName(Path.GetFullPath(song.Source)));case "_filename_ext":return Path.GetFileName(song.Source);case "_path":return Path.GetFullPath(song.Source);case "_bitrate":return song.Bitrate>0?song.Bitrate.ToString():"";case "_length":return Length(song.Duration);case "_tag":return song.TagType??"";default:throw new ArgumentException("Unbekanntes Tagfeld: "+key);}}
  public static string Types(TagLib.File file){var names=new List<string>();if((file.TagTypes&TagLib.TagTypes.Id3v1)!=0)names.Add("ID3v1");var id=file.GetTag(TagLib.TagTypes.Id3v2,false) as TagLib.Id3v2.Tag;if(id!=null)names.Add("ID3v2."+id.Version);var other=file.TagTypes&~(TagLib.TagTypes.Id3v1|TagLib.TagTypes.Id3v2);if(other!=TagLib.TagTypes.None)names.Add(other.ToString());return String.Join(" / ",names);}
 }
}
